contract InvMutTest {
    C c;

    constructor() { c = new C(0, "", ""); }
    function __ESBMC_reverted() internal returns (bool) {}
    function __ESBMC_assume(bool) internal pure {}
    receive() external payable {}

    function run(address to, uint256 value) public payable {
        require(to != address(0));

        address from = address(this);
        uint256 fromBefore = c.balanceOf(from); if (__ESBMC_reverted()) return;
        uint256 toBefore = c.balanceOf(to); if (__ESBMC_reverted()) return;
        uint256 supplyBefore = c.totalSupply(); if (__ESBMC_reverted()) return;
        bool fromFrozen = c.frozenAccount(from); if (__ESBMC_reverted()) return;
        bool toFrozen = c.frozenAccount(to); if (__ESBMC_reverted()) return;

        bool reverted;
        c.transfer(to, value); bool __rev0 = __ESBMC_reverted(); if (__rev0) {
            reverted = true;
        } else {
            reverted = false;
        }

        uint256 fromAfter = c.balanceOf(from); if (__ESBMC_reverted()) return;
        uint256 toAfter = c.balanceOf(to); if (__ESBMC_reverted()) return;
        uint256 supplyAfter = c.totalSupply(); if (__ESBMC_reverted()) return;

        assert(
            (
                reverted
                && (fromFrozen || toFrozen || fromBefore < value)
                && fromAfter == fromBefore
                && toAfter == toBefore
                && supplyAfter == supplyBefore
            ) || (
                !reverted
                && !fromFrozen
                && !toFrozen
                && fromBefore >= value
                && fromAfter == fromBefore - value
                && (
                    (to == from && toAfter == toBefore)
                    || (to != from && toAfter == toBefore + value)
                )
                && supplyAfter == supplyBefore
            )
        );
    }
}

